from websockets.asyncio.client import connect
from urllib.parse import urlencode
async def main():
 params={'sample_rate':16000,'speech_model':'u3-rt-pro','domain':'medical-v1','speaker_labels':'true','redact_pii':'true','redact_pii_policies':json.dumps(['person_name','phone_number','us_social_security_number']),'redact_pii_sub':'entity_name'}
 try:
